[ "$DRY" -eq 1 ] || say "files: 54 written"

# --- prune what a previous bundle left behind ------------------------------------------------
# An angle that was renamed or retired would otherwise keep loading forever: the harness reads
# every file in agents/, not the ones this bundle happens to ship.
if [ "$DRY" -eq 0 ]; then
  PREFIX="$PREFIX" MANIFEST_NEW='{"generatedAt":"2026-10-06T09:55:00.889Z","files":[".claude/CLAUDE.md",".claude/agents/contracts.md",".claude/agents/error-paths.md",".claude/agents/external-data.md",".claude/agents/fix-diff.md",".claude/agents/flow.md",".claude/agents/half-fix.md",".claude/agents/leak-review.md",".claude/agents/seams.md",".claude/agents/tests.md",".claude/agents/type-design.md",".claude/agents/value-integrity.md",".claude/agents/verify-finding.md",".claude/pipeline/apply-batch.js",".claude/pipeline/ask-lang.js",".claude/pipeline/export-rules.js",".claude/pipeline/gate-check.js",".claude/pipeline/install-hooks.js",".claude/pipeline/leak-check.js",".claude/pipeline/make-bundle.js",".claude/pipeline/no-poll.js",".claude/pipeline/reply-lang.js",".claude/pipeline/stats.js",".claude/pipeline/test.js",".claude/pipeline/tested-tree.js",".claude/pipeline/lib/checks.js",".claude/pipeline/lib/digest.js",".claude/pipeline/lib/git.js",".claude/pipeline/lib/hook.js",".claude/pipeline/lib/lang.js",".claude/pipeline/lib/late.js",".claude/pipeline/lib/ledger.js",".claude/pipeline/lib/parallel.js",".claude/pipeline/lib/release.js",".claude/pipeline/lib/repofile.js",".claude/pipeline/lib/root.js",".claude/pipeline/lib/stacks.js",".claude/pipeline/lib/transcript.js",".claude/pipeline/tests/_harness.js",".claude/pipeline/tests/agents.test.js",".claude/pipeline/tests/applybatch.test.js",".claude/pipeline/tests/bundle.test.js",".claude/pipeline/tests/checks.test.js",".claude/pipeline/tests/digest.test.js",".claude/pipeline/tests/leak.test.js",".claude/pipeline/tests/ledger.test.js",".claude/pipeline/tests/mods.test.js",".claude/pipeline/tests/nopoll.test.js",".claude/pipeline/tests/parallel.test.js",".claude/pipeline/tests/release.test.js",".claude/pipeline/tests/replylang.test.js",".claude/pipeline/tests/stacks.test.js",".claude/pipeline/tests/stats.test.js",".claude/pipeline/tests/testedtree.test.js"]}' node -e '
    const fs = require("fs"), path = require("path");
    const root = process.env.PREFIX;
    const mfPath = path.join(root, ".claude", "pipeline", "bundle-manifest.json");
    const next = JSON.parse(process.env.MANIFEST_NEW);
    let prev = { files: [] };
    try { prev = JSON.parse(fs.readFileSync(mfPath, "utf8")); } catch {}
    const keep = new Set(next.files);
    const stale = (prev.files || []).filter((f) => !keep.has(f));
    for (const rel of stale) {
      const p = path.join(root, rel);
      try { fs.unlinkSync(p); console.log("pruned: " + rel); } catch {}
    }
    fs.writeFileSync(mfPath, JSON.stringify(next, null, 1), "utf8");
  '
fi

# --- acceptance BEFORE wiring anything up ----------------------------------------------------
if [ "$DRY" -eq 1 ]; then
  say "would run the regression suite, then register the Stop, UserPromptSubmit, SessionStart and PreToolUse (no-poll, ask-lang) hooks"
  say "dry run: nothing was written"
  exit 0
fi
if node "$PREFIX/.claude/pipeline/test.js" --prefix "$PREFIX" >/dev/null 2>&1; then
