  say "nothing of this runs automatically. See why:"
  say "  node $PREFIX/.claude/pipeline/test.js --prefix $PREFIX"
  exit 1
fi

# --- hooks -----------------------------------------------------------------------------------
if [ ! -f "$PREFIX/.claude/settings.json" ]; then
